  while (k < n) {
    if (k > SIZE_MAX / 2)
      oc_fail(c, "array capacity overflow");
    k *= 2;
  }
  oc_value *v = (oc_value *)oc_alloc(c, k, sizeof(*v));
  unsigned char *p = (unsigned char *)oc_alloc(c, k, 1);
  if (o->element_capacity) {
    memcpy(v, o->elements, o->element_capacity * sizeof(*v));
    memcpy(p, o->element_present, o->element_capacity);
  }
